# Corrected Phase 19 historical-forecast verification
# Reconstructed audit utility (2026-11-20), NOT the original forecasting script.
# Author: Peter Sarpong
#
# Input generated by scripts/phase19_corrected_forecasting.R:
#   Phase19_Corrected_Forecast_Results/phase16_rolling_predictions.csv
# Archived accuracy targets in repository:
#   results/tables/table5_corrected_accuracy.csv
#
# Run from the repository root; no manuscript or figure files are produced.
# IMPORTANT: never use the uncorrected Phase16_R_Results output in this audit.

pred_file <- "Phase19_Corrected_Forecast_Results/phase16_rolling_predictions.csv"
reference_file <- "results/tables/table5_corrected_accuracy.csv"
audit_dir <- "reproducibility_checks"
dir.create(audit_dir, showWarnings=FALSE, recursive=TRUE)

if (!file.exists(pred_file)) {
  stop("Corrected prediction file missing. Run scripts/phase19_corrected_forecasting.R ",
       "from the repository root. DO NOT substitute the uncorrected Phase16_R_Results file.")
}
if (!file.exists(reference_file)) {
  stop("Archived accuracy table missing: ", reference_file)
}
x <- read.csv(pred_file, stringsAsFactors=FALSE, check.names=FALSE)
ref <- read.csv(reference_file, stringsAsFactors=FALSE, check.names=FALSE)
required <- c("origin","target_start","sector","target_period","model",
              "target_value","prediction")
if (!all(required %in% names(x))) {
  stop("Missing columns: ", paste(setdiff(required,names(x)),collapse=", "))
}
if (!all(c("model","predictions","MAE_pp","RMSE_pp","Bias_pp") %in% names(ref))) {
  stop("Unexpected archived table5 schema")
}
x$origin <- as.Date(x$origin)
x$target_start <- as.Date(x$target_start)
if (anyNA(x$origin) || anyNA(x$target_start)) stop("Invalid dates")
if (any(!is.finite(x$target_value)) || any(!is.finite(x$prediction))) {
  stop("Missing or non-finite target/prediction")
}
expected_models <- c("Random forest","Persistence","Ridge (fixed lambda=5)")
if (!setequal(unique(x$model),expected_models)) {
  stop("Wrong model labels in corrected prediction file")
}
key <- c("origin","sector","target_period","model")
if (anyDuplicated(x[key])) stop("Duplicate model-target rows")
target_key <- c("origin","sector","target_period")
target_count <- aggregate(x$model, x[target_key], length)
if (any(target_count$x != 3L)) stop("Unmatched three-model target records")

# The final corrected evaluation has 20 origins, 15 sectors, and exactly
# 300 matched targets per model, all with an 11-day origin-to-target-start gap.
if (length(unique(x$origin))!=20L || length(unique(x$sector))!=15L ||
    nrow(x)!=900L) stop("Unexpected evaluation size: expected 900 rows")
lead <- as.integer(x$target_start-x$origin)
if (any(lead != 11L)) {
  stop("Corrected main evaluation no longer has uniform 11-day horizons")
}

# One target value per industry, period and forecast origin.
target_range <- aggregate(x$target_value, x[target_key],
                          function(z) max(z)-min(z))
if (any(target_range$x > 1e-10)) stop("Targets differ across matched models")

x$err <- x$prediction-x$target_value
x$ae <- abs(x$err)
x$se <- x$err^2
by_model <- split(x,x$model)
metrics <- do.call(rbind,lapply(names(by_model),function(m){
  z <- by_model[[m]]
  data.frame(model=m,predictions=nrow(z),
             MAE_pp=mean(z$ae),
             RMSE_pp=sqrt(mean(z$se)),
             Bias_pp=mean(z$err))
}))
rownames(metrics) <- NULL
audit <- merge(ref,metrics,by="model",suffixes=c("_archive","_rerun"))
audit <- audit[match(ref$model,audit$model),]
if (nrow(audit)!=3L || anyNA(audit)) stop("Missing model comparison")
for (metric in c("MAE_pp","RMSE_pp","Bias_pp")) {
  audit[[paste0(metric,"_delta")]] <-
    audit[[paste0(metric,"_rerun")]]-audit[[paste0(metric,"_archive")]]
}
if (any(audit$predictions_archive != 300L) ||
    any(audit$predictions_rerun != 300L)) stop("Wrong model record counts")
write.csv(audit,file.path(audit_dir,"phase19_corrected_accuracy_audit.csv"),
          row.names=FALSE)

# Tight accuracy tolerance: the archived run should match, rather than
# merely return a similar headline percentage.
deltas <- unlist(audit[,grep("_delta$",names(audit)),drop=FALSE])
print(audit)
if(any(abs(deltas)>1e-4)) {
  stop("FAIL: Rerun metrics differ from the archived corrected results. ",
       "Inspect phase19_corrected_accuracy_audit.csv before reporting reproduction.")
}
rf <- metrics$MAE_pp[metrics$model=="Random forest"]
persistence <- metrics$MAE_pp[metrics$model=="Persistence"]
cat(sprintf(
  "PASS: corrected forecast metrics matched archived results; RF MAE %.6f pp, persistence MAE %.6f pp, gain %.4f%%.\n",
  rf,persistence,100*(persistence-rf)/persistence
))
cat("This verifies the numerical historical re-evaluation only, not historical original-release data vintages or prospective accuracy.\n")
